/**
 * The Quadradão 1.0's imported art (card NEW-20261022-ORQ-uno-no-jogo): the 8 views of the Uno generated by the Codex
 * (evidence NEW-20261021-ORQ-uno-8-lados, t2, approved by the user), cut by scripts/import-uno.mjs into one 4×2 sheet of
 * square cells, all at one scale, the wheels on the 85 % line and each view centred. Until the sheet is in (or when it
 * fails) the renderer keeps the provisional boxes (figures.ts).
 * Pure rules (tested): which view shows the car's nose for a heading and a camera view, its scale and its ground anchor.
 */
import {isoOffset} from './iso.ts';
import {CAR_HALF} from './figures.ts';

export const UNO_KEY='chaveiro:quadradao';
export const UNO_URL='/art/lite/veiculos/quadradao.webp';
/** The sheet's square cell (px) and the wheels' line in it (share of the cell from the top). */
export const UNO_CELL=320,UNO_FOOT=.85;
/** The sheet's views in frame order (row 1: S, SO, O, NO; row 2: N, NE, L, SE): where the nose points on the screen. */
export const UNO_VIEWS=['S','SO','O','NO','N','NE','L','SE'] as const;
export type UnoView=typeof UNO_VIEWS[number];
/**
 * World px per sheet px: the diagonal views (a car along a world axis) as wide as the provisional car's footprint,
 * (length + width) × 42 px (SE is 281 px wide in the sheet); the side views come out as long as its body.
 */
export const UNO_SCALE=2*(CAR_HALF.l+CAR_HALF.w)*42/281;

/** Screen octants from the right, clockwise (y down), to the sheet's frames. */
const OCTANT_FRAME=[6,7,0,1,2,3,4,5];

/**
 * The sheet frame of a car at `heading` (radians in the world plane) for the camera `view`: the nose's direction on the
 * screen, the iso squash undone (y × 2) so a car along a world axis takes a diagonal view, cut in 8 octants.
 */
export function unoFrame(heading:number,view:number):number{
  const o=isoOffset(Math.cos(heading),Math.sin(heading),0,view);
  const a=Math.atan2(o.y*2,o.x),octant=((Math.round(a/(Math.PI/4))%8)+8)%8;
  return OCTANT_FRAME[octant];
}

/** The lowest point of the car's footprint below its centre on the screen (px): where the sheet's wheel line sits. */
export function unoFootY(heading:number,view:number):number{
  const c=Math.cos(heading),s=Math.sin(heading);let low=0;
  for(const [u,w] of [[1,1],[1,-1],[-1,1],[-1,-1]]){
    const dx=u*CAR_HALF.l*c-w*CAR_HALF.w*s,dy=u*CAR_HALF.l*s+w*CAR_HALF.w*c;
    low=Math.max(low,isoOffset(dx,dy,0,view).y);
  }
  // the wheels stand a little inside the body's corners
  return low*.85;
}
